  "misconception": {
    "pack_id": null,
    "wrong": "Выделение межзерновых коллекторов работает на любой глубине и при любой промывочной жидкости.",
    "right": "Приёмы рассчитаны на терригенные разрезы до 4—5 км, со слабой и средней уплотнённостью, при пресном глинистом растворе.",
    "claims": ["c1", "c2", "c3"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Глубина интервала: до 4—5 км или свыше.", "claims": ["c1", "c2"], "hypothesis": false},
      {"text": "Степень уплотнённости пород: слабая, средняя или высокая.", "claims": ["c1"], "hypothesis": false},
      {"text": "Тип промывочной жидкости: пресный глинистый раствор или техническая вода, нередко минерализованная.", "claims": ["c1", "c3"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Решение, применим ли приём межзернового коллектора к интервалу.", "claims": ["c1"], "hypothesis": true}
    ],
    "breaks": [
      {"text": "Глубже 4—5 км задача существенно усложняется.", "claims": ["c2", "c4"], "hypothesis": false},
      {"text": "Техническая вода нередко минерализована, и это усложняет задачу.", "claims": ["c3", "c4"], "hypothesis": false},
      {"text": "Граница 4—5 км дана диапазоном, поэтому интервалы рядом с ней решаются неоднозначно.", "claims": ["c1"], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Как проверка входных данных перед запуском модели: модель работает только в диапазоне условий, на которых её обучили. Вне диапазона результат не гарантирован.",
    "breaks_where": "Граница 4—5 км у автора задана словами и диапазоном, а не обучающей выборкой. Модель и пласт устроены по-разному."
  },
  "now_nuance": {
    "text": "По современной практике (гипотеза): скважины часто бурят глубже 4—5 км и на минерализованных растворах. Для этого используют более новые приборы и обработку. Конкретные приборы в этом узле не разбирались."
  },
  "threshold": {
    "is_threshold": true,
    "why": "Без понимания условий применимости новичок перенесёт приёмы на любые скважины и получит ошибочные выделения коллекторов."
  },
